class Channel {
  std::vector<std::function<void(const Message&)>> taps_;
 public:
  void publish(const Message& m) {
    for (auto& tap : taps_) tap(copy_for_tap(m));  // independent copy
    primary_.deliver(m);                           // original, unchanged
  }
  void add_tap(std::function<void(const Message&)> f) { taps_.push_back(std::move(f)); }
};

void *frontend = zmq_socket(ctx, ZMQ_XSUB);
void *backend  = zmq_socket(ctx, ZMQ_XPUB);
void *capture  = zmq_socket(ctx, ZMQ_PUSH);
zmq_bind(frontend, "tcp://*:5555");
zmq_bind(backend,  "tcp://*:5556");
zmq_bind(capture,  "tcp://*:5557");
zmq_proxy(frontend, backend, capture);  // all messages also to capture

